theorem sum_abs_latVal_le {t : ℝ} (ht : 1 < t) (n : ℕ) {h : ℝ}
    (hh : ∑' k : ℕ, (t⁻¹) ^ k * (latVal t n k) ^ 2 ≤ h) :
