theorem half_pow_le_signed_legVal {t : ℝ} (ht : 2 ≤ t) {n : ℕ}
    (hn : 4 * gaussConst t ^ 2 ≤ t ^ n) :
    t ^ degTerm n n / 2 ≤ (-1) ^ n * legVal t n

